  "store.ladder.skipNote": { en: "If you're not sure, starting from Level 1 is still recommended — progress in the early levels is the foundation for the next ones. You can always come back to any mission later.", id: "Kalau ragu, tetap disarankan mulai dari Level 1 — progress di level awal jadi fondasi buat level berikutnya. Kamu selalu bisa balik ke mission mana pun nanti." },
  "store.ladder.growSocial.question": { en: "Have you (or this brand) been through a growth process like this before?", id: "Kamu (atau brand ini) udah pernah jalanin proses growth kayak gini sebelumnya?" },
  "store.ladder.growSocial.progression": { en: "The numbers at each level are cumulative (total since the start), not monthly targets — but engagement quality and consistency have to hold the whole time. Viral spikes, or bought followers or engagement, can't be used to skip a level (bought followers still count as starting below 1,000). Minimum active time: Level 1 → 8 weeks, Level 2 → 12 weeks, Level 3 → 16 weeks, Level 4 → 20 weeks, Level 5 → 24 weeks. No more than 14 days in a row without posting.", id: "Angka di tiap level itu kumulatif (total sejak awal), bukan target bulanan — tapi kualitas & konsistensi engagement harus tetap terjaga sepanjang periode. Lonjakan viral, followers, atau engagement yang dibeli nggak bisa dipakai buat lompat level (followers beli tetap dihitung mulai dari kisaran di bawah 1.000). Minimal aktif: Level 1 → 8 minggu, Level 2 → 12 minggu, Level 3 → 16 minggu, Level 4 → 20 minggu, Level 5 → 24 minggu. Maksimal vakum 14 hari berturut-turut." },
  "store.ladder.growPersonal.question": { en: "Have you been through a personal branding process like this before?", id: "Kamu udah pernah jalanin proses bangun personal branding kayak gini sebelumnya?" },
  "store.ladder.growPersonal.progression": { en: "The goal isn't just \"more followers\" — it's Visibility → Credibility → Authority → Influence → Opportunity. A personal brand works when attention turns into trust, relationships, influence, and real opportunities. The numbers at each level are cumulative (total since the start). Minimum active time: Level 1 → 8 weeks, Level 2 → 12 weeks, Level 3 → 16 weeks, Level 4 → 20 weeks, Level 5 → 24 weeks. No more than 14 days in a row without posting — a one-off viral spike doesn't count as sustainable growth.", id: "Tujuannya bukan cuma \"nambah followers\" — tapi Visibility → Credibility → Authority → Influence → Opportunity. Personal brand dianggap berhasil kalau perhatian berubah jadi kepercayaan, hubungan, pengaruh, dan peluang nyata. Angka tiap level kumulatif (total sejak awal). Minimal aktif: Level 1 → 8 minggu, Level 2 → 12 minggu, Level 3 → 16 minggu, Level 4 → 20 minggu, Level 5 → 24 minggu. Maksimal vakum 14 hari berturut-turut — lonjakan viral sesaat nggak dihitung sebagai growth yang berkelanjutan." },
  "store.ladder.growPersonal.termsIntro": { en: "Before you start, read and agree to this campaign's ground rules.", id: "Sebelum mulai, baca dan setujui aturan main campaign ini dulu." },
  "store.terms.gp.1.title": { en: "Authenticity first", id: "Keaslian Dulu" },
  "store.terms.gp.1.body": { en: "Your personal brand has to represent a real person — your actual expertise, experience, opinions, and values, not a fictional character.", id: "Personal branding harus merepresentasikan orang asli — keahlian, pengalaman, opini, dan values kamu yang beneran, bukan karakter fiktif." },
  "store.terms.gp.2.title": { en: "Organic growth only", id: "Growth Organik Aja" },
  "store.terms.gp.2.body": { en: "Buying followers, likes, comments, or views, and using fake accounts, bots, engagement pods, follow-for-follow, or any other artificial growth tactic isn't allowed.", id: "Beli followers, likes, komentar, views, akun palsu, bot, engagement pod, follow-for-follow, atau cara growth artifisial lainnya nggak boleh." },
  "store.terms.gp.3.title": { en: "Stay consistent", id: "Harus Konsisten" },
  "store.terms.gp.3.body": { en: "Growth has to be proven over time. No more than 14 days in a row without posting.", id: "Growth harus kebukti sepanjang waktu. Maksimal vakum 14 hari berturut-turut." },
  "store.terms.gp.4.title": { en: "Content with real value", id: "Konten yang Ada Value-nya" },
  "store.terms.gp.4.body": { en: "Content has to give real value — through knowledge, experience, perspective, education, stories, or useful insight. Pure self-promotion doesn't count as thought-leadership content.", id: "Konten harus kasih value asli — lewat ilmu, pengalaman, sudut pandang, edukasi, cerita, atau insight yang berguna. Promosi diri doang nggak dihitung sebagai konten thought-leadership." },
  "store.terms.gp.5.title": { en: "Quality over follower count", id: "Kualitas di Atas Jumlah Followers" },
  "store.terms.gp.5.body": { en: "Followers alone don't level you up. Authority, engagement quality, conversations, network growth, and opportunities have to grow too.", id: "Followers doang nggak nentuin kamu naik level. Otoritas, kualitas engagement, percakapan, pertumbuhan network, dan peluang juga harus ikut naik." },
  "store.terms.gp.6.title": { en: "No fake authority", id: "Nggak Boleh Otoritas Palsu" },
  "store.terms.gp.6.body": { en: "Don't make up credentials, achievements, testimonials, clients, expertise, or professional experience.", id: "Nggak boleh ngarang kredensial, pencapaian, testimoni, klien, keahlian, atau pengalaman profesional." },
  "store.terms.gp.7.title": { en: "Proof required", id: "Perlu Bukti" },
  "store.terms.gp.7.body": { en: "You may be asked to show analytics, content links, collaboration records, event records, or other proof.", id: "Kamu mungkin diminta nunjukkin analytics, link konten, catatan kolaborasi, catatan event, atau bukti lain." },
  "store.terms.gp.8.title": { en: "Every milestone is required", id: "Semua Milestone Wajib" },
  "store.terms.gp.8.body": { en: "Hitting the follower target alone doesn't unlock the next level — every milestone in that level has to be done first.", id: "Nyampe target followers doang nggak otomatis buka level berikutnya — semua milestone di level itu harus kelar dulu." },

