  "store.terms.ev.intro": { en: "Before this event campaign starts, read and agree to its ground rules.", id: "Sebelum campaign event ini mulai, baca dan setujui aturan mainnya dulu." },
  "store.terms.ev.1.title": { en: "Keep it authentic", id: "Autentik" },
  "store.terms.ev.1.body": { en: "The whole campaign has to be run authentically, with no data manipulation.", id: "Seluruh campaign harus dijalankan secara autentik dan nggak boleh pakai manipulasi data." },
