  "store.terms.ev.6.title": { en: "Dynamic targets", id: "Target Dinamis" },
  "store.terms.ev.6.body": { en: "Targets can differ between campaigns depending on role, scale, audience, objective, duration, platform, and past performance.", id: "Target bisa beda-beda antar campaign tergantung role, skala, audiens, tujuan, durasi, platform, dan performa sebelumnya." },
