  "store.terms.ev.7.body": { en: "An event campaign has a deadline set by the event date. It moves on to the next phase even if earlier milestones weren't reached.", id: "Campaign event punya deadline berdasarkan tanggal event. Campaign tetap jalan ke fase berikutnya meskipun milestone sebelumnya belum tercapai." },
  "store.terms.ev.8.title": { en: "Missed milestones", id: "Milestone Terlewat" },
  "store.terms.ev.8.body": { en: "A missed milestone doesn't mean the campaign failed — the system records it as MISSED or PARTIALLY COMPLETED so you can review it.", id: "Milestone yang nggak tercapai bukan berarti campaign gagal — sistem catat sebagai TERLEWAT atau SEBAGIAN SELESAI buat bahan evaluasi." },
  "store.terms.ev.9.title": { en: "No rewriting the past", id: "Nggak Boleh Manipulasi Mundur" },
  "store.terms.ev.9.body": { en: "Don't change actual numbers after a deadline just to boost your achievement.", id: "Kamu nggak boleh ubah data aktual setelah deadline cuma buat naikin angka pencapaian." },
  "store.terms.ev.10.title": { en: "Clear measurement", id: "Pengukuran Jelas" },
  "store.terms.ev.10.body": { en: "Every milestone needs a clear way to measure it.", id: "Setiap milestone harus punya cara pengukuran yang jelas." },
  "store.terms.ev.11.title": { en: "Required vs. optional", id: "Wajib vs Opsional" },
  "store.terms.ev.11.body": { en: "Required milestones serve the campaign's main objective. Optional milestones are extras and don't affect whether the core campaign is complete.", id: "Milestone wajib dipakai buat tujuan utama campaign. Milestone opsional cuma tambahan dan nggak memengaruhi penyelesaian campaign inti." },
  "store.terms.ev.12.title": { en: "When a campaign is done", id: "Campaign Selesai" },
  "store.terms.ev.12.body": { en: "A campaign is done once it has gone through every set phase (Pre-event → Event day → Post-event) — not based on how many milestones were hit.", id: "Campaign dianggap selesai kalau udah lewatin semua fase yang ditentukan (Pra-event → Hari-H → Pasca-event) — bukan berdasarkan jumlah milestone yang berhasil." },
