  // goalRepeat / goalReferrals labels as-is; only the labels below are new.
  "store.ms.goalSalesTotal": { en: "Total sold", id: "Total terjual" },
  "store.ms.goalSalesOffer": { en: "Clear offer: price, how to order, and proof", id: "Penawaran jelas: harga, cara order, dan bukti" },
  "store.ms.goalSalesRevenue": { en: "Revenue", id: "Omzet" },
  "store.unit.unit": { en: "units", id: "unit" },
