  "store.unit.pesanan": { en: "orders", id: "pesanan" },
  "store.mission.sal1.name": { en: "First Sales", id: "Penjualan Pertama" },
  "store.mission.sal1.desc": { en: "Focus: people discover you, get interested, and the first ones buy. Make the offer impossible to misunderstand, then collect proof from every buyer.", id: "Fokus: orang nemu kamu, tertarik, lalu yang pertama mulai beli. Bikin penawaranmu nggak mungkin disalahpahami, lalu kumpulkan bukti dari tiap pembeli." },
  "store.mission.sal1.tagline": { en: "Proof that it sells comes before selling more.", id: "Bukti laku dulu, baru jualan lebih banyak." },
  "store.mission.sal2.name": { en: "Steady Sales", id: "Penjualan Rutin" },
  "store.mission.sal2.desc": { en: "Focus: people who are considering it actually buy — week after week, not just on lucky days. Answer everyone who asks and keep the proof coming.", id: "Fokus: orang yang lagi menimbang beneran jadi beli — tiap minggu, bukan cuma pas hoki. Balas semua yang tanya dan terus tambah buktinya." },
  "store.mission.sal2.tagline": { en: "One good week is luck. A steady month is a business.", id: "Seminggu ramai itu hoki. Sebulan stabil itu bisnis." },
  "store.mission.sal3.name": { en: "Loyal Customers", id: "Pelanggan Setia" },
  "store.mission.sal3.desc": { en: "Focus: buyers who buy again and recommend you to others. This is where selling starts getting easier instead of harder.", id: "Fokus: pembeli yang beli lagi dan merekomendasikanmu ke orang lain. Di sinilah jualan mulai makin gampang, bukan makin berat." },
  "store.mission.sal3.tagline": { en: "Buy → buy again → recommend you.", id: "Beli → beli lagi → merekomendasikanmu." },
  "camp.m.src.totalSold": { en: "Total sold (sum of your products)", id: "Total terjual (jumlah semua produkmu)" },
  "camp.m.home.salesSum": { en: "added up from the numbers you log per product", id: "dijumlah dari angka yang kamu catat per produk" },
  "goal.ms.soldDesc": { en: "Follows Sales Tracker automatically — log each sale there and this number updates itself. BrandLab can't read sales data on its own, so the tracker is where it comes from.", id: "Ikut Sales Tracker otomatis — catat tiap penjualan di sana, angka ini update sendiri. BrandLab belum bisa baca data penjualan sendiri, jadi sumbernya dari tracker." },
  "goal.ms.totalSoldDesc": { en: "The sum of every product's sold number, all counted in the same unit. Log sales in Sales Tracker and this follows.", id: "Jumlah angka terjual semua produk, dihitung dengan satuan yang sama. Catat penjualan di Sales Tracker, angka ini ikut." },
  "goal.ms.offerClearDesc": { en: "Can a stranger tell in 10 seconds what you sell, what it costs, and how to order? Put price, how to order and one piece of proof where people land first (bio, pinned post, catalogue).", id: "Orang asing bisa paham dalam 10 detik nggak: kamu jual apa, harganya berapa, dan cara ordernya? Taruh harga, cara order, dan satu bukti di tempat orang pertama mendarat (bio, pinned post, katalog)." },
  "goal.ms.revenueDesc": { en: "Optional, in Rupiah, logged by you. Tracked on its own — never mixed with the sold count.", id: "Opsional, dalam Rupiah, kamu yang catat. Dilacak sendiri — nggak pernah dicampur dengan jumlah terjual." },
  "goal.rules.sales": { en: "This campaign only tracks your sales — and every number in it is one you log yourself, because BrandLab can't read sales data automatically. Log sales in Sales Tracker and the numbers here follow. With more than one product, the total (same unit for all) opens the next level; each product keeps its own row.", id: "Campaign ini cuma melacak penjualanmu — dan semua angkanya kamu yang catat sendiri, karena BrandLab belum bisa baca data penjualan otomatis. Catat penjualan di Sales Tracker, angka di sini ikut. Kalau produknya lebih dari satu, total (satuannya sama) yang membuka level berikutnya; tiap produk tetap punya barisnya sendiri." },
  "goal.place.firstSales": { en: "Suggested start: Level {n} ({name}) — you're still collecting your first sales and the proof that comes with them.", id: "Saran mulai: Level {n} ({name}) — kamu masih ngumpulin penjualan pertama dan bukti-buktinya." },
  "goal.place.steadySales": { en: "Suggested start: Level {n} ({name}) — it already sells; the work now is making it steady.", id: "Saran mulai: Level {n} ({name}) — sudah terbukti laku; PR-nya sekarang bikin penjualannya rutin." },
