  "cross.salesFlat.text": { en: "Your visibility is growing, but sales aren't moving with it. It may be worth checking how clear the offer is, whether your content tells people what to do next, and how easy it is to actually buy.", id: "Visibilitasmu tumbuh, tapi penjualan belum ikut bergerak. Mungkin perlu dicek: sejelas apa penawaranmu, apakah kontenmu ngasih tahu orang harus ngapain, dan segampang apa proses belinya." },
  "cross.salesFlat.detail": { en: "Social Media Growth is at {socialPct}% of its current target; Sales Growth is at {salesPct}% (from the numbers you logged). This is a pattern, not a proven cause.", id: "Social Media Growth ada di {socialPct}% dari targetnya; Sales Growth di {salesPct}% (dari angka yang kamu catat). Ini pola, bukan sebab yang terbukti." },
  "cross.inquiriesAhead.text": { en: "People are asking, but fewer are buying than the questions suggest. The gap is usually somewhere between the question and the payment.", id: "Orang sudah tanya-tanya, tapi yang jadi beli lebih sedikit dari yang nanya. Celahnya biasanya ada di antara pertanyaan dan pembayaran." },
  "cross.inquiriesAhead.detail": { en: "Inquiries this level are at {inquiryPct}% of target while sold is at {salesPct}% — both from numbers you logged.", id: "Inquiry di level ini sudah {inquiryPct}% dari target, sementara terjual baru {salesPct}% — dua-duanya dari angka yang kamu catat." },
