  "cross.socialAhead.text": { en: "Your visibility is growing faster than your community. Consider inviting more of your engaged followers into it.", id: "Visibilitasmu tumbuh lebih cepat dari komunitasmu. Coba ajak lebih banyak followers yang aktif buat gabung." },
  "cross.socialAhead.detail": { en: "Social Media Growth is at {socialPct}% of its current target; Community Growth is at {communityPct}%.", id: "Social Media Growth ada di {socialPct}% dari targetnya; Community Growth ada di {communityPct}%." },
