  "goal.stage.momentum.name": { en: "Momentum", id: "Momentum" },
  "goal.stage.momentum.desc": { en: "Double down on the formats that proved themselves; drop the ones that didn't.", id: "Gandakan format yang terbukti jalan, tinggalkan yang nggak." },
  "goal.stage.expand.name": { en: "Expand", id: "Perluas" },
  "goal.stage.expand.desc": { en: "Reach new people through collaborations and content made to be shared.", id: "Jangkau orang baru lewat kolaborasi dan konten yang gampang di-share." },
  "goal.stage.expand.desc.community": { en: "Get members creating with you — UGC, shared activities, their stories.", id: "Ajak member ikut bikin — UGC, aktivitas bareng, cerita mereka." },
