  "goal.wizard.uploadsFromCadence": { en: "From your work schedule. It sets the content targets and how fast growth can realistically go.", id: "Dari Jadwal Kerja-mu. Ini menentukan target konten dan seberapa cepat pertumbuhan yang masuk akal." },
  "goal.wizard.seePlan": { en: "See my levels", id: "Lihat level-ku" },
